class Solution:
    def maxSubarrays(self, n, conflictingPairs):
        by = [[] for _ in range(n+1)]
        for a, b in conflictingPairs:
            if a > b: a, b = b, a
            by[b].append(a)
        gain = [0]*(n+2)
        f = s = 0
        tot = 0
        for r in range(1, n+1):
            for a in by[r]:
                if a > f:
                    s = f; f = a
                elif a > s:
                    s = a
            tot += r - f
            if f:
                gain[f] += f - s
        return tot + max(gain)

