class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        M = 10**9+7
        L = len(s)
        f = [1]*(L+2)
        for i in range(1, L+2):
            f[i] = f[i-1]*i % M
        inv = [pow(x, M-2, M) for x in f]
        def C(n, r):
            if r < 0 or r > n:
                return 0
            return f[n]*inv[r] % M*inv[n-r] % M
        steps = [0]*(L+2)
        for c in range(2, L+2):
            steps[c] = steps[bin(c).count('1')]+1
        good = [c for c in range(1, L+1) if steps[c] <= k-1]
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                m = L-i-1
                for c in good:
                    ans += C(m, c-ones)
                ones += 1
        return ans % M

