import sys,random
def main():
    D=sys.stdin.buffer.read().split();n,m,q=int(D[0]),int(D[1]),int(D[2])
    A=[0]*m;B=[0]*m;T=[0]*m;H=[0]*m
    for i in range(m):
        s=int(D[3+2*i]);t=int(D[4+2*i])
        T[i]=1 if s<t else 0
        A[i]=min(s,t);B[i]=max(s,t);H[i]=random.getrandbits(60)+1
    bit=[[0]*(n+2),[0]*(n+2)]
    def upd(f,i,v):
        while i<=n:
            f[i]+=v;i+=i&-i
    def pre(f,i):
        s=0
        while i>0:
            s+=f[i];i-=i&-i
        return s
    cl=[0]*(n+2);cr=[0]*(n+2)
    def add(i,sg):
        f=bit[T[i]];h=H[i]*sg
        upd(f,A[i],h);upd(f,B[i],-h);cl[A[i]]+=sg;cr[B[i]]+=sg
    lo=[0]*m;l=0
    for r in range(m):
        a=A[r];b=B[r];f=bit[T[r]]
        while l<r:
            if cl[a] or cr[b] or pre(f,b-1)!=pre(f,a):
                add(l,-1);l+=1
            else:break
        add(r,1);lo[r]=l
    out=[]
    p=3+2*m
    for k in range(q):
        L=int(D[p])-1;R=int(D[p+1])-1;p+=2
        out.append("Yes" if L>=lo[R] else "No")
    print("\n".join(out))
main()

