import sys
def main():
    d=sys.stdin.read().split()
    n,m=int(d[0]),int(d[1])
    adj=[0]*n
    for i in range(m):
        u=int(d[2+2*i])-1;v=int(d[3+2*i])-1
        adj[u]|=1<<v;adj[v]|=1<<u
    rows=[a for a in adj if a]
    piv=[]
    r=0
    for c in range(n):
        s=None
        for i in range(r,len(rows)):
            if rows[i]>>c&1:
                s=i;break
        if s is None: continue
        rows[r],rows[s]=rows[s],rows[r]
        for i in range(len(rows)):
            if i!=r and rows[i]>>c&1:
                rows[i]^=rows[r]
        piv.append(c)
        r+=1
    ps=set(piv)
    X=[0]*n
    j=0
    for f in range(n):
        if f in ps: continue
        vec=1<<f
        for i,p in enumerate(piv):
            if rows[i]>>f&1:
                vec|=1<<p
        for v in range(n):
            if vec>>v&1:
                X[v]|=1<<j
        j+=1
    if all(X):
        print("Yes")
        print(*X)
    else:
        print("No")
main()

