import sys
def main():
    MOD=998244353
    d=sys.stdin.read().split()
    N,M,K=int(d[0]),int(d[1]),int(d[2])
    X=d[3:3+M]
    b=sum(1 for j in range(M-1) if X[j]!=X[j+1])
    F=[1]*(2005)
    for i in range(1,2005):F[i]=F[i-1]*i%MOD
    IF=[pow(f,MOD-2,MOD) for f in F]
    def C(n,r):
        if r<0 or r>n or n<0:return 0
        return F[n]*IF[r]%MOD*IF[n-r]%MOD
    k=K-1
    G=[0]*(N+1)
    for l in range(N+1):
        s=0
        for i in range(k+1):
            s+=(-1)**i*C(k,i)*pow(k-i,l,MOD)
        G[l]=s%MOD
    def mul(a,c):
        r=[0]*(N+1)
        for i,x in enumerate(a):
            if x:
                for j in range(N+1-i):
                    r[i+j]+=x*c[j]
        return [v%MOD for v in r]
    res=[0]*(N+1);res[0]=1
    base=G;e=M
    while e:
        if e&1:res=mul(res,base)
        e>>=1
        if e:base=mul(base,base)
    T=N-(M-1+b)
    if T<0:
        print(0);return
    ans=0
    for n in range(T+1):
        if b==0:
            h=1 if n==0 else 0
        else:
            h=C(n+b-1,n)*pow(K-2,n,MOD)%MOD
        ans+=res[T-n]*h
    print(ans%MOD)
main()

