        def order(d):
            di,dj=D[d]
            ri=range(n-1,-1,-1) if di==1 else range(n)
            rj=range(m-1,-1,-1) if dj==1 else range(m)
            return ri,rj
        def ok(v,w):
            return w==2 if v in(0,1) else w==0
        S=[]
        for d in range(4):
            di,dj=D[d]
            a=[[1]*m for _ in range(n)]
            ri,rj=order(d)
            for i in ri:
                for j in rj:
                    x=i+di;y=j+dj
                    if 0<=x<n and 0<=y<m and ok(grid[i][j],grid[x][y]):
                        a[i][j]=1+a[x][y]
            S.append(a)
        best=0
        for d in range(4):
            di,dj=D[d]
            e=(d+1)%4
            ei,ej=D[e]
            t=[[1]*m for _ in range(n)]
            ri,rj=order(d)
            for i in ri:
                for j in rj:
                    v=grid[i][j]
                    r=1
                    x=i+di;y=j+dj
                    if 0<=x<n and 0<=y<m and ok(v,grid[x][y]):
                        r=1+t[x][y]
                    x=i+ei;y=j+ej
                    if 0<=x<n and 0<=y<m and ok(v,grid[x][y]):
                        r=max(r,1+S[e][x][y])
                    t[i][j]=r
                    if v==1 and r>best:best=r
        return best

