class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k))
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        reach = [None] * (h + 1)
        base = [False] * k
        base[0] = True
        reach[h] = base
        for i in range(h - 1, -1, -1):
            nxt = reach[i + 1]
            lo = 1 if i == 0 else 0
            cur = [False] * k
            wi = w[i]
            for r in range(k):
                for d in range(lo, 10):
                    if nxt[(r - d * wi) % k]:
                        cur[r] = True
                        break
            reach[i] = cur
        res = []
        cur = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (cur - d * w[i]) % k
                if reach[i + 1][nr]:
                    res.append(str(d))
                    cur = nr
                    break
        s = "".join(res)
        if n % 2:
            return s + s[:-1][::-1]
        return s + s[::-1]

