class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt=[0]*26
        for ch in s: cnt[ord(ch)-97]+=1
        n=len(s)
        best=n
        for f in range(1,n+1):
            st={0:0}
            for c in cnt:
                ns={}
                for p,cost in st.items():
                    # option target 0
                    o=[(cost+c,0),(cost+c,c)]
                    if p<f:
                        need=f-p
                        if c>=need:
                            e=c-need
                            o.append((cost+e,0)); o.append((cost+e,e))
                        else:
                            o.append((cost+need-c,0))
                    else:
                        o.append((cost+c,0)); o.append((cost+c,c))
                    for cs,k in o:
                        if k not in ns or ns[k]>cs: ns[k]=cs
                st=ns
            m=min(st.values())
            if m<best: best=m
        return best

