        key=(loc,t)
        r=memo.get(key)
        if r is not None: return r
        res=False
        for i in range(k):
            if loc[i]==t:
                base=loc[:i]+(2,)+loc[i+1:]
                if not win(base,1-t):
                    res=True;break
                vi=v[i]
                for j in range(k):
                    if base[j]==2 and v[j]<vi:
                        nl=base[:j]+(t,)+base[j+1:]
                        if not win(nl,1-t):
                            res=True;break
                if res:break
        memo[key]=res
        return res
    print("Takahashi" if win(tuple(loc),0) else "Aoki")
sys.setrecursionlimit(10000)
