class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')
        def occ(q):
            l = len(q)
            if l == 0:
                return [True]*(n+1)
            t = q+'\x00'+s
            m = len(t)
            z = [0]*m
            L = R = 0
            for i in range(1, m):
                k = 0
                if i < R:
                    k = min(R-i, z[i-L])
                while i+k < m and t[k] == t[i+k]:
                    k += 1
                z[i] = k
                if i+k > R:
                    L = i; R = i+k
            res = [False]*(n+1)
            for i in range(n):
                if z[l+1+i] >= l:
                    res[i] = True
            return res
        A = occ(a); B = occ(b); C = occ(c)
        la, lb, lc = len(a), len(b), len(c)
        last = [-1]*(n+1)
        cur = -1
        for i in range(n+1):
            if A[i]:
                cur = i
            last[i] = cur
        nxt = [-1]*(n+2)
        cur = -1
        for i in range(n, -1, -1):
            if C[i]:
                cur = i
            nxt[i] = cur
        best = -1
        for j in range(n-lb+1):
            if B[j] and j-la >= 0:
                ai = last[j-la]
                ci = nxt[j+lb]
                if ai >= 0 and ci >= 0:
                    v = ci+lc-ai
                    if best < 0 or v < best:
                        best = v
        return best

