from collections import deque
def bfs(N,A):
    s=frozenset(i for i in range(N) if A>>i&1)
    d={s:0};q=deque([s])
    while q:
        u=q.popleft()
        for i in range(N):
            v=frozenset(x+(i>x)-(i<x) for x in u)
            if v not in d:d[v]=d[u]+1;q.append(v)
    return d
