class Solution:
    def findAnswer(self, parent, s):
        n = len(s)
        ch = [[] for _ in range(n)]
        for i in range(1, n):
            ch[parent[i]].append(i)
        start = [0]*n
        end = [0]*n
        order = []
        st = [(0, 0)]
        while st:
            x, e = st.pop()
            if e:
                order.append(s[x])
                end[x] = len(order)-1
            else:
                start[x] = len(order)
                st.append((x, 1))
                for y in reversed(ch[x]):
                    st.append((y, 0))
        t = '#' + '#'.join(order) + '#'
        m = len(t)
        p = [0]*m
        c = r = 0
        for i in range(m):
            if i < r:
                p[i] = min(r-i, p[2*c-i])
            while i-p[i]-1 >= 0 and i+p[i]+1 < m and t[i-p[i]-1] == t[i+p[i]+1]:
                p[i] += 1
            if i+p[i] > r:
                c = i
                r = i+p[i]
        return [p[start[i]+end[i]+1] >= end[i]-start[i]+1 for i in range(n)]

