        inf = float('inf')
        best = [inf] * k
        best[0] = 0
        p = 0
        ans = -inf
        for j in range(1, len(nums) + 1):
            p += nums[j - 1]
            r = j % k
            if best[r] != inf and p - best[r] > ans:
                ans = p - best[r]
            if p < best[r]:
                best[r] = p
        return ans

