class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        M = 10**9 + 7
        c = [0] * 26
        for ch in s:
            c[ord(ch) - 97] += 1
        for _ in range(t):
            z = c[25]
            c = [z] + c[:25]
            c[1] = (c[1] + z) % M
        return sum(c) % M

