    def countPairs(self, nums):
        def reach(x):
            s = str(x).zfill(7)
            r = {s}
            for i in range(7):
                for j in range(i+1, 7):
                    l = list(s)
                    l[i], l[j] = l[j], l[i]
                    r.add(''.join(l))
            return r
        sets = [reach(x) for x in nums]
        c = 0
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                if str(nums[j]).zfill(7) in sets[i]:
                    c += 1
        return c

