from collections import Counter
class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        S = sum(nums)
        c = Counter(nums)
        best = None
        for x in c:
            r = S - x
            if r % 2:
                continue
            s = r // 2
            if s in c and (s != x or c[x] >= 2):
                if best is None or x > best:
                    best = x
        return best

