class Solution:
    def minZeroArray(self, nums, queries):
        n = len(nums)
        bits = [1]*n
        done = [0 if nums[i]==0 else -1 for i in range(n)]
        for k,(l,r,v) in enumerate(queries,1):
            for i in range(l,r+1):
                if done[i]==-1:
                    bits[i] |= bits[i]<<v
                    if (bits[i]>>nums[i])&1:
                        done[i]=k
        if -1 in done: return -1
        return max(done)

