import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N=10000
        pr=[True]*N
        pr[0]=pr[1]=False
        for i in range(2,N):
            if pr[i]:
                for j in range(i*i,N,i): pr[j]=False
        if pr[n] or pr[m]: return -1
        L=len(str(n))
        d={n:n}
        h=[(n,n)]
        while h:
            c,u=heapq.heappop(h)
            if c>d[u]: continue
            if u==m: return c
            s=str(u).zfill(L)
            for i in range(L):
                for dd in (-1,1):
                    x=int(s[i])+dd
                    if x<0 or x>9: continue
                    if i==0 and x==0 and L>1: continue
                    v=int(s[:i]+str(x)+s[i+1:])
                    if pr[v]: continue
                    nc=c+v
                    if nc<d.get(v,1<<60):
                        d[v]=nc
                        heapq.heappush(h,(nc,v))
        return -1

