class Solution:
    def maxRemovals(self, source, pattern, targetIndices):
        n=len(source); m=len(pattern)
        t=set(targetIndices)
        NEG=-10**9
        dp=[NEG]*(m+1); dp[0]=0
        for i in range(n):
            c=1 if i in t else 0
            ch=source[i]
            for j in range(min(i+1,m),-1,-1):
                v=dp[j]+c if dp[j]>=0 else NEG
                if j and ch==pattern[j-1] and dp[j-1]>v:
                    v=dp[j-1]
                dp[j]=v
        return dp[m]

