import heapq
class Solution:
    def minMaxWeight(self, n, edges, threshold):
        g=[[] for _ in range(n)]
        for a,b,w in edges:
            g[b].append((a,w))
        INF=float('inf')
        d=[INF]*n
        d[0]=0
        h=[(0,0)]
        while h:
            c,u=heapq.heappop(h)
            if c>d[u]:
                continue
            for v,w in g[u]:
                m=max(c,w)
                if m<d[v]:
                    d[v]=m
                    heapq.heappush(h,(m,v))
        r=max(d)
        return -1 if r==INF else r

