from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        s = set(map(tuple, points))
        best = -1
        for a in points:
            for b in points:
                if a[0] < b[0] and a[1] < b[1] and (a[0], b[1]) in s and (b[0], a[1]) in s:
                    corners = {(a[0], a[1]), (b[0], b[1]), (a[0], b[1]), (b[0], a[1])}
                    ok = True
                    for p in s:
                        if p not in corners and a[0] <= p[0] <= b[0] and a[1] <= p[1] <= b[1]:
                            ok = False
                            break
                    if ok:
                        best = max(best, (b[0] - a[0]) * (b[1] - a[1]))
        return best

